#!/usr/bin/env node
/**
 * Copy the renderer's stylesheet into a TypeScript module.
 *
 * Grafana rejects plugins that import CSS directly — `import 'pkg/style.css'`
 * injects a global stylesheet, and a global stylesheet from one panel applies to
 * every other panel on the dashboard. The rule is right, and the fix is not to
 * smuggle the import past the check: the panel nests these rules inside its own
 * emotion class, which scopes them to this panel and nothing else.
 *
 * Emotion needs the CSS as a string, and a string is what a `.ts` module can
 * hold. The generated file is committed so the repository builds and typechecks
 * without a prebuild step; `vendorStyles.test.ts` fails if it drifts from the
 * installed package, which is what would otherwise happen silently on a
 * dependency bump.
 *
 *     node scripts/sync-vendor-styles.mjs
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const require = createRequire(import.meta.url);
const here = path.dirname(fileURLToPath(import.meta.url));

/** Resolved through the package, so it follows the installed version. */
export function readVendorCss() {
  // The package's own './style.css' export, so this follows whatever version is
  // installed rather than a path guessed at from the package root.
  const file = require.resolve('bharat-choropleth/style.css', { paths: [path.join(here, '..')] });
  return readFileSync(file, 'utf8');
}

export function renderModule(css) {
  return `/**
 * The renderer's stylesheet, as a string.
 *
 * Generated by scripts/sync-vendor-styles.mjs — do not edit. It is a string
 * rather than a CSS import because Grafana does not allow plugins to import CSS
 * directly: that injects a global stylesheet, which would apply to every other
 * panel on the dashboard. BharatPanel nests these rules inside its own emotion
 * class instead, so they reach this panel and stop there.
 */
export const vendorStyles = ${JSON.stringify(css)};
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const css = readVendorCss();
  const target = path.join(here, '..', 'src', 'vendorStyles.ts');
  writeFileSync(target, renderModule(css));
  console.log(`wrote ${path.relative(path.join(here, '..'), target)} (${css.length} bytes of CSS)`);
}
